-- Owner-approved Korean terminology: NSO = 회원국; NSA = 회원국협회.
UPDATE glossary_terms SET description_ko='대한민국의 세계스카우트연맹 회원국(NSO)이다. 원문 조직명은 Korea Scout Association이다. 소속 지역연맹: 아시아태평양지역연맹. 명칭·회원 구분 출처: 세계스카우트연맹(WOSM) 공식 디렉터리(Scouting Worldwide).',updated_at=CURRENT_TIMESTAMP WHERE id=1 AND description_ko IS '대한민국의 대표 국가스카우트조직(NSO)이다. 원문 조직명은 Korea Scout Association이다. 소속 지역연맹: 아시아태평양지역연맹. 명칭·회원 구분 출처: 세계스카우트연맹(WOSM) 공식 디렉터리(Scouting Worldwide).' AND term_ko IS '한국스카우트연맹' AND updated_at IS '2026-10-08 03:29:40';
UPDATE glossary_terms SET description_ko='세계스카우트연맹의 최고 의사결정 총회이다. 회원국의 대표들이 정책·전략·주요 결의와 세계스카우트이사회 선출 등을 논의한다. 세계스카우트이사회 및 사무국과 구분한다.',updated_at=CURRENT_TIMESTAMP WHERE id=8 AND description_ko IS '세계스카우트연맹의 최고 의사결정 총회이다. 회원 국가스카우트조직의 대표들이 정책·전략·주요 결의와 세계스카우트이사회 선출 등을 논의한다. 세계스카우트이사회 및 사무국과 구분한다.' AND term_ko IS '세계총회' AND updated_at IS '2026-10-08 01:48:24';
UPDATE glossary_terms SET description_ko='세계 각국의 회원국(NSO)이 참여하는 세계 스카우트운동의 국제 조직이다. 청소년의 교육과 성장을 지원하며, 세계스카우트총회·세계스카우트이사회·세계스카우트사무국을 중심으로 운영된다. WAGGGS와는 별개의 국제 조직이다.',updated_at=CURRENT_TIMESTAMP WHERE id=10 AND description_ko IS '국가스카우트조직(NSO)을 회원으로 하는 세계 스카우트운동의 국제 조직이다. 청소년의 교육과 성장을 지원하며, 세계스카우트총회·세계스카우트이사회·세계스카우트사무국을 중심으로 운영된다. WAGGGS와는 별개의 국제 조직이다.' AND term_ko IS '세계스카우트연맹' AND updated_at IS '2026-10-08 01:48:24';
UPDATE glossary_terms SET description_ko='아시아태평양지역연맹과 개최국 회원국이 협력하여 개최하는 국제 스카우트 야영 행사이다. 지역의 청소년이 프로그램, 야외 활동, 문화 교류를 함께 경험한다. 세계스카우트잼버리 및 각국의 전국 잼버리와 구분하며, 개최 연도·장소·참가 조건은 해당 회차 공식 공고를 기준으로 확인한다.',updated_at=CURRENT_TIMESTAMP WHERE id=33 AND description_ko IS '아시아태평양지역연맹과 개최국 국가스카우트조직이 협력하여 개최하는 국제 스카우트 야영 행사이다. 지역의 청소년이 프로그램, 야외 활동, 문화 교류를 함께 경험한다. 세계스카우트잼버리 및 각국의 전국 잼버리와 구분하며, 개최 연도·장소·참가 조건은 해당 회차 공식 공고를 기준으로 확인한다.' AND term_ko IS '아시아태평양지역 스카우트 잼버리' AND updated_at IS '2026-10-08 01:48:24';
UPDATE glossary_terms SET description_ko='세계스카우트연맹(WOSM)의 사무국으로, 세계스카우트총회와 세계스카우트이사회의 활동을 행정적·실무적으로 지원한다. 세계스카우트이사회가 임명한 사무총장(Secretary General)이 이끌며, 회원국에 대한 지원, 세계 스카우트 행사 협력, 국제 파트너십과 운영 계획 실행을 담당한다.',updated_at=CURRENT_TIMESTAMP WHERE id=48 AND description_ko IS '세계스카우트연맹(WOSM)의 사무국으로, 세계스카우트총회와 세계스카우트이사회의 활동을 행정적·실무적으로 지원한다. 세계스카우트이사회가 임명한 사무총장(Secretary General)이 이끌며, 국가스카우트조직에 대한 지원, 세계 스카우트 행사 협력, 국제 파트너십과 운영 계획 실행을 담당한다.' AND term_ko IS '세계스카우트연맹 사무국' AND updated_at IS '2026-10-08 01:50:39';
UPDATE glossary_terms SET description_ko='청년이 평화·환경·지속가능한 발전과 관련된 지역사회 문제를 탐구하고 봉사 프로젝트를 실천하는 세계스카우트연맹의 국제 활동 인증이다. 기본 과정은 탐구(Discovery, 최소 21시간), 자원봉사(Volunteering, 최소 80시간), 네트워크 참여로 구성된다. 참가 조건과 운영 방식은 각 회원국의 시행 안내를 함께 확인한다.',updated_at=CURRENT_TIMESTAMP WHERE id=60 AND description_ko IS '청년이 평화·환경·지속가능한 발전과 관련된 지역사회 문제를 탐구하고 봉사 프로젝트를 실천하는 세계스카우트연맹의 국제 활동 인증이다. 기본 과정은 탐구(Discovery, 최소 21시간), 자원봉사(Volunteering, 최소 80시간), 네트워크 참여로 구성된다. 참가 조건과 운영 방식은 각 국가스카우트조직의 시행 안내를 함께 확인한다.' AND term_ko IS '세계스카우트상' AND updated_at IS '2026-10-08 01:50:39';
UPDATE glossary_terms SET description_ko='영국의 세계스카우트연맹 회원국(NSO)이다. 원문 명칭은 The Scout Association이며 영국의 스카우트 프로그램과 지도자 활동을 지원한다. 소속 지역연맹: 유럽지역연맹. 명칭·회원 구분 출처: 세계스카우트연맹(WOSM) 공식 디렉터리(Scouting Worldwide).',updated_at=CURRENT_TIMESTAMP WHERE id=63 AND description_ko IS '영국의 대표 국가스카우트조직(NSO)이다. 원문 명칭은 The Scout Association이며 영국의 스카우트 프로그램과 지도자 활동을 지원한다. 소속 지역연맹: 유럽지역연맹. 명칭·회원 구분 출처: 세계스카우트연맹(WOSM) 공식 디렉터리(Scouting Worldwide).' AND term_ko IS '영국 스카우트연맹' AND updated_at IS '2026-10-08 03:29:40';
UPDATE glossary_terms SET description_ko='미국을 대표하는 회원국(NSO)이다. Boy Scouts of America(BSA)는 2024년 새 명칭을 발표했고, 2025년 2월 8일부터 Scouting America라는 명칭을 공식 사용한다. 회원국 현황의 옛 명칭과 현재 명칭은 같은 조직을 가리킨다. 소속 지역연맹: 인터아메리카지역연맹. 명칭 출처: Scouting America 공식 안내. 회원 구분 출처: 세계스카우트연맹(WOSM) 공식 디렉터리(Scouting Worldwide).',updated_at=CURRENT_TIMESTAMP WHERE id=64 AND description_ko IS '미국을 대표하는 국가스카우트조직(NSO)이다. Boy Scouts of America(BSA)는 2024년 새 명칭을 발표했고, 2025년 2월 8일부터 Scouting America라는 명칭을 공식 사용한다. 회원국 현황의 옛 명칭과 현재 명칭은 같은 조직을 가리킨다. 소속 지역연맹: 인터아메리카지역연맹. 명칭 출처: Scouting America 공식 안내. 회원 구분 출처: 세계스카우트연맹(WOSM) 공식 디렉터리(Scouting Worldwide).' AND term_ko IS '미국 스카우트연맹' AND updated_at IS '2026-10-08 03:29:40';
