UPDATE glossary_terms SET description_ko='이스라엘의 회원국협회(NSA)로 회원국 현황에 기재된 조직이다. 원문 명칭은 The Hebrew Scout Association이다. 대표 NSO 아래의 소속 협회와 독립된 WOSM 회원 조직을 구분한다. 확인된 한국어 공식 명칭이 없어 원문명을 유지한다. 소속 지역연맹: 유럽지역연맹. 명칭·회원 구분 출처: 세계스카우트연맹(WOSM) 공식 디렉터리(Scouting Worldwide).',updated_at=CURRENT_TIMESTAMP WHERE id=234 AND description_ko IS '이스라엘의 국가스카우트협회(NSA)로 회원국 현황에 기재된 조직이다. 원문 명칭은 The Hebrew Scout Association이다. 대표 NSO 아래의 소속 협회와 독립된 WOSM 회원 조직을 구분한다. 확인된 한국어 공식 명칭이 없어 원문명을 유지한다. 소속 지역연맹: 유럽지역연맹. 명칭·회원 구분 출처: 세계스카우트연맹(WOSM) 공식 디렉터리(Scouting Worldwide).' AND term_ko IS '' AND updated_at IS '2026-10-08 03:29:43';
